// spec: specs/edit-listing-save-changes.md (2.1–2.4) · кейсы: .qa/tests/edit-listing-save-changes/EDIT-SAVE-02..05.md
// Нужно своё объявление: QA_EDIT_LISTING_ID=<id> [QA_EDIT_LISTING_ROLE=user]; без него — skip.
// ПРОД: PATCH business?id=eq.<id> перехватывается и отвечается локально (на сервер не уходит), прочие не-GET — abort.
// Поэтому тест проверяет запрос сохранения (тело, количество) и поведение страницы, но не реальную запись в базе.
import { test, expect } from '@playwright/test';
import {
  EDIT_ID, EDIT_ROLE, SKIP_REASON, LOAD, SAVE, NEXT, UPDATE, TITLE_PH, PHONE_PH,
  interceptEdit, openEdit, expectStepButtons, expectNoConfirmations,
} from './edit-listing.helpers';

test.use({ storageState: `../auth/${EDIT_ROLE}.json`, serviceWorkers: 'block' });

test.describe('Редактирование объявления — «שמור שינויים» (#357a06)', () => {
  test.skip(!EDIT_ID, SKIP_REASON);

  for (const device of ['@desktop', '@android']) {
    test(`Кнопка «שמור שינויים» на шагах 1–5 #357a06 ${device}`, async ({ page }) => {
      const { passed, state } = await interceptEdit(page, EDIT_ID);
      await openEdit(page, EDIT_ID, state);
      // «מה רצוי»: «בכל שלב»; «שלב הבא נשאר»; на шаге 5 — «עדכן מודעה»
      for (let step = 1; step <= 4; step++) {
        await expectStepButtons(page, NEXT, step);
        await page.getByRole('button', { name: NEXT }).click();
      }
      await expectStepButtons(page, UPDATE, 5);
      expect(passed, 'ни один не-GET запрос не дошёл до прода').toEqual([]);
    });

    test(`Заголовок на шаге 1 → «שמור שינויים»: один PATCH, без подтверждений, статус прежний #357a06 ${device}`, async ({ page }) => {
      const { patches, passed, state } = await interceptEdit(page, EDIT_ID);
      await openEdit(page, EDIT_ID, state);
      const title = page.getByPlaceholder(TITLE_PH);
      const newTitle = `QA-AUTO ${(await title.inputValue()).replace(/^QA-AUTO /, '')}`.slice(0, 90);
      await title.fill(newTitle);

      await page.getByRole('button', { name: SAVE, exact: true }).click();
      await page.waitForURL(/\/mybusinesses/, LOAD);

      expect(patches.length, 'ровно один PATCH business?id=eq.<id>').toBe(1);
      const body = patches[0].body;
      expect(Object.values(body), 'в теле PATCH новая כותרת').toContain(newTitle);
      if ('status' in body) {
        expect(body.status, 'статус в PATCH = текущий (не сбрасывается)').toBe(state.row!.status);
      }
      await expectNoConfirmations(page);
      expect(passed, 'ни один не-GET запрос не дошёл до прода').toEqual([]);
    });
  }

  test('Правка на шаге 1 → «שלב הבא» → «שמור שינויים» на шаге 2 сохраняет правку #357a06 @desktop', async ({ page }) => {
    const { patches, passed, state } = await interceptEdit(page, EDIT_ID);
    await openEdit(page, EDIT_ID, state);
    const title = page.getByPlaceholder(TITLE_PH);
    const newTitle = `QA-AUTO ${(await title.inputValue()).replace(/^QA-AUTO /, '')}`.slice(0, 90);
    await title.fill(newTitle);
    await page.getByRole('button', { name: NEXT }).click();
    await expect(page.getByText('משך פעילות העסק (שנים/חודשים)'), 'шаг 2 «נתונים נוספים»').toBeVisible(LOAD);

    await page.getByRole('button', { name: SAVE, exact: true }).click();
    await page.waitForURL(/\/mybusinesses/, LOAD);

    expect(patches.length, 'сохранение отправлено').toBeGreaterThan(0);
    const last = patches[patches.length - 1].body;
    expect(Object.values(last), 'последний PATCH содержит правку с шага 1').toContain(newTitle);
    if ('status' in last) expect(last.status, 'статус прежний').toBe(state.row!.status);
    expect(passed, 'ни один не-GET запрос не дошёл до прода').toEqual([]);
  });

  test('Пустая כותרת / пустой телефон — сообщение, PATCH не уходит #357a06 @desktop', async ({ page }) => {
    const { patches, passed, state } = await interceptEdit(page, EDIT_ID);
    await openEdit(page, EDIT_ID, state);
    const title = page.getByPlaceholder(TITLE_PH);
    const phone = page.getByPlaceholder(PHONE_PH);
    const oldTitle = await title.inputValue();

    await title.fill('');
    await page.getByRole('button', { name: SAVE, exact: true }).click();
    await expect(page.getByText('אנא הזן כותרת לעסק').first(), 'сообщение о пустой כותרת (F-10 AC 03)').toBeVisible(LOAD);
    await expect(page, 'остаёмся в редактировании').toHaveURL(/\/addbusiness/);

    await title.fill(oldTitle);
    await phone.fill('');
    await page.getByRole('button', { name: SAVE, exact: true }).click();
    await expect(page.getByText('אנא הזן מספר טלפון ליצירת קשר').first(), 'сообщение о пустом телефоне (F-10 AC 03)').toBeVisible(LOAD);
    await expect(page).toHaveURL(/\/addbusiness/);

    expect(patches, 'PATCH сохранения не уходил').toEqual([]);
    expect(passed, 'ни один не-GET запрос не дошёл до прода').toEqual([]);
  });
});
